PRAGMA foreign_keys=OFF;
BEGIN;
CREATE TABLE molis_storage_space (singleton INTEGER PRIMARY KEY CHECK(singleton=1), space_id TEXT NOT NULL, descriptor TEXT NOT NULL);
CREATE TABLE personal_planning_method_packs (
      method_id TEXT PRIMARY KEY,
      version INTEGER NOT NULL,
      enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)),
      pack_json TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
INSERT INTO "molis_storage_space"("singleton","space_id","descriptor") VALUES(1,'space_golden_root_home','{"spaceId":"space_golden_root_home","kind":"local","ownerUserId":null,"teamId":null,"issuer":null,"applicationId":null}');
INSERT INTO "personal_planning_method_packs"("method_id","version","enabled","pack_json","created_at","updated_at") VALUES('golden-seed',2,1,'{"kind":"domain","summary":"先用项目与模块 SSOT 固定边界，再按横纵模块、实现、集成和交付组织软件工作。","applies_to":["应用开发","服务开发","工程改造"],"domain_tags":["software","engineering","app"],"steps":["先确认产品目标、用户行为、完成标准和不做什么","建立或核对项目级 SSOT，明确全局不变量、权威状态与决策位置、模块索引和跨模块契约","用纵向端到端结果和横向共享能力划分模块，解决状态、契约、决策与写入面的重叠","在模块地图稳定后并行撰写模块 SSOT，固定各自所有权、输入输出、消费者、异常恢复和 Impact surfaces","从模块 SSOT 派生实现 Goal；实现只等待自己消费的契约，能用 test double、fixture 或兼容层独立验证时让提供者与消费者并行","让集成、端到端验收、迁移、发布和恢复消费全部相关模块的可运行产物"],"required_coverage":[{"area":"core_function","label":"核心功能","question":"哪条真实用户或调用路径必须工作？"},{"area":"user_journey","label":"端到端用户旅程","question":"用户如何进入、完成并从异常中恢复？"},{"area":"interaction_ui","label":"交互与 UI","question":"人如何观察和控制系统？"},{"area":"content_information","label":"内容与信息","question":"系统需要呈现和保存哪些信息？"},{"area":"project_ssot","label":"项目级 SSOT","question":"哪个仓库文档唯一说明项目结果、非目标、全局不变量、权威状态、模块索引、跨模块契约和验证来源；现有文档是否可信且仍然有效？"},{"area":"module_architecture","label":"横纵模块地图","question":"哪些纵向模块各自拥有端到端结果，哪些横向模块向多个消费者提供共享能力；每个重要状态、数据、契约和决策由谁唯一拥有？"},{"area":"module_ssot_contracts","label":"模块级 SSOT","question":"每个模块的 SSOT 在哪里，是否明确职责与非职责、输入输出、公共契约、消费者、异常恢复和验收？"},{"area":"parallel_impact_boundaries","label":"并发写入边界","question":"计划并行的 Goal 分别读取、写入、决定或独占哪些 Impact surfaces；是否存在未解决的重叠？"}],"dependency_rules":[{"rule_id":"project-ssot-after-product-plan","statement":"项目级 SSOT 消费已经确认的产品目标、用户行为、完成标准和非目标；产品计划不反向依赖技术实现。","direction_hint":"project SSOT depends_on confirmed product plan"},{"rule_id":"module-ssot-after-project-ssot","statement":"模块 SSOT 消费项目级全局不变量、模块地图和跨模块契约；各模块文档在地图稳定后可以并行撰写。","direction_hint":"module SSOT depends_on project SSOT and module map"},{"rule_id":"implementation-after-module-ssot","statement":"模块实现依赖自己已经稳定且可验证的模块 SSOT，以及它真实消费的提供者公共契约。","direction_hint":"module implementation depends_on its module SSOT and consumed provider contract"},{"rule_id":"provider-consumer-implementations-parallel","statement":"提供者与消费者只通过稳定契约交互，且消费者能用 test double、fixture 或兼容层独立验证时，两边实现保持并行，不互设 depends_on。","direction_hint":"keep provider and consumer implementations parallel after contract"},{"rule_id":"integration-after-module-implementations","statement":"集成、端到端验收、发布和恢复验证消费提供者与消费者双方的可运行产物。","direction_hint":"integration and release depend_on provider and consumer implementations"},{"rule_id":"contract-before-consumer","statement":"消费者实现依赖稳定且可验证的提供者契约。","direction_hint":"consumer depends_on provider contract"},{"rule_id":"output-consumption","statement":"只有下游 Goal 明确消费上游 Goal 的可验收结果时才建立 depends_on。","direction_hint":"consumer depends_on provider"},{"rule_id":"decision-before-commitment","statement":"会改变后续范围或方案的决定必须先于不可逆投入。","direction_hint":"commitment depends_on decision"},{"rule_id":"proof-before-close","statement":"验证 Goal 消费被验证结果和完成标准，而不是反向依赖实现。","direction_hint":"verification depends_on deliverable"},{"rule_id":"hierarchy-is-not-dependency","statement":"父子归属、同一阶段或同一负责人不自动构成执行依赖。","direction_hint":"use part_of for hierarchy; keep independent goals parallel"}],"evidence_requirements":["项目级 SSOT 与模块索引的可读取引用","每个模块 SSOT 与公共契约的可读取引用","模块唯一所有权和 Impact 读写面核对","定向测试、构建或类型检查与真实主路径"],"completion_checks":["项目级事实与模块事实没有重复权威位置","每个状态、数据、公共契约和决策面只有一个所有者","计划并行的 Goal 没有冲突的 write、decide 或 exclusive surface","提供者与消费者的依赖落在契约或真实运行产物上，而不是组织顺序","输入输出、错误路径、发布与恢复可执行"],"failure_modes":["按 UI、API、数据库、前后端文件夹或团队分工机械拆模块","把根 SSOT 写成复制全部模块细节的巨型文档","两个模块共同维护同一状态或公共契约","把所有共享代码塞进没有真实消费者边界的横向模块","让消费者实现无条件等待提供者实现，而不是先稳定契约并评估并行","单元测试通过就宣称产品可用","无异常和迁移路径"],"source_refs":["Molis Work engineering protocol","User-confirmed SSOT decomposition requirement (2026-08-28)"],"confidence":0.96,"enabled":true,"method_id":"golden-seed","name":"金样方法 seed 已改","scope":"personal","version":2,"created_at":"2026-01-15T09:00:00.000Z","updated_at":"2026-01-15T09:00:00.000Z","event_types":[],"default_requirements":[],"instructions":"# 金样方法 seed 已改\n\n## 作用\n先用项目与模块 SSOT 固定边界，再按横纵模块、实现、集成和交付组织软件工作。\n\n适用于：应用开发、服务开发、工程改造。\n\n## Runtime 应该怎么规划\n1. 先确认产品目标、用户行为、完成标准和不做什么\n2. 建立或核对项目级 SSOT，明确全局不变量、权威状态与决策位置、模块索引和跨模块契约\n3. 用纵向端到端结果和横向共享能力划分模块，解决状态、契约、决策与写入面的重叠\n4. 在模块地图稳定后并行撰写模块 SSOT，固定各自所有权、输入输出、消费者、异常恢复和 Impact surfaces\n5. 从模块 SSOT 派生实现 Goal；实现只等待自己消费的契约，能用 test double、fixture 或兼容层独立验证时让提供者与消费者并行\n6. 让集成、端到端验收、迁移、发布和恢复消费全部相关模块的可运行产物\n\n规划不是把上面的步骤机械变成一串 Goal。先用这些步骤把问题想完整，再把每个能独立交付、独立验收的结果设为 Goal；同一 Goal 不要混入多个主要结果。\n\n## 有限 Goal 与持续运行\nGoal 必须描述一项有限、可验收、最终能完成的改变。首次建立能力、流程或工具可以是 Goal；能力建立后的持续运行属于 recurring operation，不应为了保持循环可见而把能力 Goal 留成永久未完成 Goal，也不应把业务循环写成循环 depends_on。\n\n持续运行用笔记和报告留下可追溯事实。笔记或报告暴露真实问题或改进机会时，用意图创建一条有限的改进 Goal，或通过 Goal Tree 提案调整结构，由用户决定是否采纳；不要自动创建或批准新 Goal。本轮规划沿用现有笔记、报告、意图和树能力表达重复运行中的有限改进，不要为了保持循环可见而新增调度器或 Operation 数据模型。\n\n## 拆分时必须回答\n1. **核心功能**：哪条真实用户或调用路径必须工作？\n2. **端到端用户旅程**：用户如何进入、完成并从异常中恢复？\n3. **交互与 UI**：人如何观察和控制系统？\n4. **内容与信息**：系统需要呈现和保存哪些信息？\n5. **项目级 SSOT**：哪个仓库文档唯一说明项目结果、非目标、全局不变量、权威状态、模块索引、跨模块契约和验证来源；现有文档是否可信且仍然有效？\n6. **横纵模块地图**：哪些纵向模块各自拥有端到端结果，哪些横向模块向多个消费者提供共享能力；每个重要状态、数据、契约和决策由谁唯一拥有？\n7. **模块级 SSOT**：每个模块的 SSOT 在哪里，是否明确职责与非职责、输入输出、公共契约、消费者、异常恢复和验收？\n8. **并发写入边界**：计划并行的 Goal 分别读取、写入、决定或独占哪些 Impact surfaces；是否存在未解决的重叠？\n\n没有答案的关键问题必须进入待确认事项，不能用含糊 Goal 掩盖。遗漏任一与当前任务相关的覆盖项，都视为规划不完整。\n\n## 如何判断 depends_on\ndepends_on 只表达“结果消费”：如果 B 开始或完成时必须使用 A 的可验收产出，就设置 B depends_on A。方向永远从消费结果的 Goal 指向提供结果的 Goal。\n\n1. 项目级 SSOT 消费已经确认的产品目标、用户行为、完成标准和非目标；产品计划不反向依赖技术实现。\n   - 方向：project SSOT depends_on confirmed product plan\n2. 模块 SSOT 消费项目级全局不变量、模块地图和跨模块契约；各模块文档在地图稳定后可以并行撰写。\n   - 方向：module SSOT depends_on project SSOT and module map\n3. 模块实现依赖自己已经稳定且可验证的模块 SSOT，以及它真实消费的提供者公共契约。\n   - 方向：module implementation depends_on its module SSOT and consumed provider contract\n4. 提供者与消费者只通过稳定契约交互，且消费者能用 test double、fixture 或兼容层独立验证时，两边实现保持并行，不互设 depends_on。\n   - 方向：keep provider and consumer implementations parallel after contract\n5. 集成、端到端验收、发布和恢复验证消费提供者与消费者双方的可运行产物。\n   - 方向：integration and release depend_on provider and consumer implementations\n6. 消费者实现依赖稳定且可验证的提供者契约。\n   - 方向：consumer depends_on provider contract\n7. 只有下游 Goal 明确消费上游 Goal 的可验收结果时才建立 depends_on。\n   - 方向：consumer depends_on provider\n8. 会改变后续范围或方案的决定必须先于不可逆投入。\n   - 方向：commitment depends_on decision\n9. 验证 Goal 消费被验证结果和完成标准，而不是反向依赖实现。\n   - 方向：verification depends_on deliverable\n10. 父子归属、同一阶段或同一负责人不自动构成执行依赖。\n   - 方向：use part_of for hierarchy; keep independent goals parallel\n\n上面每条依赖判断规则都必须逐条判定。规则描述真实产出消费时，它就是不能跳过的硬依赖，必须建立对应的 depends_on；规则明确要求保持并行时，不得为了排列顺序添加依赖；规则不适用时，要能说明当前任务里缺少哪一种产出消费关系，不能静默略过。\n\n不要因为讨论顺序、期望执行时间、同属一个父 Goal、修改同一文件或由同一人负责就建立 depends_on。父子归属使用 part_of 表达；没有结果消费关系的工作应保持并行。\n\n建立或修改依赖后，检查整张图：没有循环；每个依赖都能说清上游产出和下游用途；关键交付没有缺失前置；执行顺序应从无未完成依赖的底层 Goal 开始。\n\n## 与其他主题一起规划\n不要只围绕当前讨论最显眼的主题拆 Goal。把当前方法与其他已选方法放在一起，列出每个主题产生的关键结果、消费这些结果的主题，以及两者之间是否存在真实前置关系。若某个消费者需要产品定义、用户动线、市场证据、数据集、评测基线、技术契约、权限流程、研究证据或其他专业产出，而当前方法组合没有覆盖提供者，就召回相应主题的方法再完成拆分。\n\n跨主题关系的常见模式包括：市场证据支持产品决定；产品目标和用户动线约束技术方案；技术契约与基础能力被功能实现消费；数据与评测支撑 AI 能力；研究证据支撑内容主张；角色与权限支撑运营流程；已验证的核心循环支撑游戏内容生产。这些只是召回线索，不是固定模板。只有消费者无法在缺少提供者产出的情况下正确开始或完成时，才建立硬依赖；一般相关、可以独立验证或仅需最终对齐的主题保持并行。\n\n## 完成前需要的证据\n1. 项目级 SSOT 与模块索引的可读取引用\n2. 每个模块 SSOT 与公共契约的可读取引用\n3. 模块唯一所有权和 Impact 读写面核对\n4. 定向测试、构建或类型检查与真实主路径\n\n## 收口检查\n1. 项目级事实与模块事实没有重复权威位置\n2. 每个状态、数据、公共契约和决策面只有一个所有者\n3. 计划并行的 Goal 没有冲突的 write、decide 或 exclusive surface\n4. 提供者与消费者的依赖落在契约或真实运行产物上，而不是组织顺序\n5. 输入输出、错误路径、发布与恢复可执行\n\n## 常见误拆\n1. 按 UI、API、数据库、前后端文件夹或团队分工机械拆模块\n2. 把根 SSOT 写成复制全部模块细节的巨型文档\n3. 两个模块共同维护同一状态或公共契约\n4. 把所有共享代码塞进没有真实消费者边界的横向模块\n5. 让消费者实现无条件等待提供者实现，而不是先稳定契约并评估并行\n6. 单元测试通过就宣称产品可用\n7. 无异常和迁移路径\n\n## 用户提出新要求时\n先把新要求与现有 Goal、已确认产出和依赖图对照，找出直接受影响的 Goal 及其下游消费者。保留未受影响且仍然成立的 Goal；只新增、修改、失效或重连受影响部分，然后重新检查覆盖项、依赖方向、循环、遗漏和可执行顺序。不要为了让新要求看起来已被处理而重写整棵树，也不要静默改变已确认的目标。\n\n## 提交规划前\n逐项说明：为什么这样拆；每条 depends_on 消费什么产出；哪些 Goal 可以并行；当前最底层、可立即执行的 Goal 是什么；哪些问题仍需用户决定。"}','2026-01-15T09:00:00.000Z','2026-01-15T09:00:00.000Z');
PRAGMA user_version=1;
COMMIT;
